use jcompat::jtime::instant_of;
use marathon_config::{
    AppleTarget, MarathonDevices, SimulatorProfile, SshAuthentication, Transport, Worker,
    binding::{BindingCause, BindingContext, Profile, ValidationStage},
    pipeline::{LoadError, bind_devices_bytes},
};
use serde_json::{Value as Json, json};
use std::{collections::HashSet, fs, path::PathBuf};

fn context() -> BindingContext {
    BindingContext {
        profile: Profile::Marathondevices,
        marathonfile: PathBuf::from("/elsewhere/Marathonfile"),
        marathonfile_dir: PathBuf::from("/elsewhere"),
        process_dir: PathBuf::from("/process"),
        environment: Vec::new(),
        now: instant_of(0, 0).unwrap(),
        analytics_tracking: false,
        bugsnag_reporting: false,
    }
}

fn bind(text: &str) -> std::result::Result<MarathonDevices, LoadError> {
    bind_devices_bytes(text.as_bytes(), &context())
}

fn js(text: &str) -> String {
    text.into()
}

