#[test]
fn test_sample1() {
    let src = fs::read_to_string(
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../fixtures/vendor-apple-base/fixtures/marathondevices/sample_1.yaml"),
    )
    .unwrap();
    let actual = bind(&src).unwrap();
    assert_eq!(
        actual,
        MarathonDevices {
            workers: vec![
                Worker {
                    transport: Transport::Local,
                    devices: vec![
                        AppleTarget::Simulator { udid: js("XXX") },
                        AppleTarget::Physical { udid: js("YYY") },
                    ],
                },
                Worker {
                    transport: Transport::Ssh {
                        addr: js("node-1.device-farm.example.com"),
                        port: 44,
                        authentication: Some(SshAuthentication::Password {
                            username: js("vasya"),
                            password: js("pupking"),
                        }),
                        check_reachability: true,
                    },
                    devices: vec![AppleTarget::SimulatorProfile(SimulatorProfile {
                        device_type_id: js("com.apple.CoreSimulator.SimDeviceType.iPhone-X"),
                        runtime_id: Some(js("com.apple.CoreSimulator.SimRuntime.iOS-16-2")),
                        new_name_prefix: js("prefix"),
                    })],
                },
            ],
        }
    );
}

// ---- AppleTargetTest ----------------------------------------------------------

#[test]
fn test_fq_ids() {
    let profile = SimulatorProfile {
        device_type_id: js("iPhone X"),
        runtime_id: Some(js("watchOS 3.2")),
        new_name_prefix: js("marathon"),
    };
    assert_eq!(
        profile.fully_qualified_device_type_id().to_owned(),
        "com.apple.CoreSimulator.SimDeviceType.iPhone-X"
    );
    assert_eq!(
        profile.fully_qualified_runtime_id().map(|s| s.to_owned()),
        Some("com.apple.CoreSimulator.SimRuntime.watchOS-3-2".to_owned())
    );
}

#[test]
fn fq_id_expansion_edges() {
    let expand = |device: &str, runtime: Option<&str>| {
        let profile = SimulatorProfile {
            device_type_id: js(device),
            runtime_id: runtime.map(js),
            new_name_prefix: js("marathon"),
        };
        (
            profile.fully_qualified_device_type_id().to_owned(),
            profile.fully_qualified_runtime_id().map(|s| s.to_owned()),
        )
    };
    // Already fully qualified: verbatim, dots kept.
    assert_eq!(
        expand(
            "com.apple.CoreSimulator.SimDeviceType.iPhone-X",
            Some("com.apple.CoreSimulator.SimRuntime.iOS-16-2")
        ),
        (
            "com.apple.CoreSimulator.SimDeviceType.iPhone-X".to_owned(),
            Some("com.apple.CoreSimulator.SimRuntime.iOS-16-2".to_owned())
        )
    );
    // A runtime FQCN in the deviceType field gets the device-type prefix in
    // front of it (the startsWith check is against the other FQCN).
    assert_eq!(
        expand("com.apple.CoreSimulator.SimRuntime.iOS-16-2", None),
        (
            "com.apple.CoreSimulator.SimDeviceType.com-apple-CoreSimulator-SimRuntime-iOS-16-2".to_owned(),
            None
        )
    );
    // No dot-boundary check: a mere prefix counts as qualified.
    assert_eq!(
        expand("com.apple.CoreSimulator.SimDeviceTypeX", None).0,
        "com.apple.CoreSimulator.SimDeviceTypeX"
    );
}

// ---- Transport / hashing ------------------------------------------------------

#[test]
fn transport_id_and_hash_keys() {
    assert_eq!(Transport::Local.id().to_owned(), "local");
    let ssh = Transport::Ssh {
        addr: js("192.168.1.10"),
        port: 22,
        authentication: None,
        check_reachability: true,
    };
    assert_eq!(ssh.id().to_owned(), "192.168.1.10:22");
    // DeviceTracker (5.4) keys maps by Transport/AppleTarget.
    let mut set: HashSet<Transport> = HashSet::new();
    set.insert(ssh.clone());
    assert!(set.contains(&ssh));
    let keyed = |key: &str| Transport::Ssh {
        addr: "worker".into(),
        port: 22,
        authentication: Some(SshAuthentication::PublicKey {
            username: "user".into(),
            key: PathBuf::from(key),
        }),
        check_reachability: true,
    };
    let plain = keyed("keys/id");
    let dotted = keyed("keys/./id");
    assert_ne!(plain, dotted);
    assert_eq!(HashSet::from([plain, dotted]).len(), 2);
    let mut targets: HashSet<AppleTarget> = HashSet::new();
    targets.insert(AppleTarget::Host);
    assert!(targets.contains(&AppleTarget::Host));
}

// ---- Copied Marathondevices fixtures -------------------------------------------

#[test]
fn marathondevices_fixtures_bind() {
    let dir =
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/vendor-apple-ios/fixtures/marathondevices");
    // empty.yaml's `devices:` is an explicit null for a non-null creator
    // parameter: the JVM rejects it with MissingKotlinParameterException
    // (corpus row worker-devices-null), and so does the port.
    let mut bound = 0;
    for entry in fs::read_dir(&dir).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let text = fs::read_to_string(&path).unwrap();
        match bind(&text) {
            Ok(devices) => {
                assert_ne!(name, "empty.yaml", "empty.yaml must not bind");
                assert_eq!(devices.workers.len(), 1, "{name}");
                bound += 1;
            }
            Err(LoadError::Configuration(error)) => {
                assert_eq!(name, "empty.yaml", "{name} must bind: {error:?}");
                assert_eq!(
                    error.class.to_owned(),
                    "com.fasterxml.jackson.module.kotlin.MissingKotlinParameterException"
                );
            }
            Err(other) => panic!("{name}: {other:?}"),
        }
    }
    assert_eq!(bound, 9);
}

#[test]
fn fake_worker_apple_marathondevices_bind() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/fake-worker/apple");
    let mut bound = 0;
    for scenario in fs::read_dir(&root).unwrap() {
        let file = scenario.unwrap().path().join("in/Marathondevices");
        if file.exists() {
            let text = fs::read_to_string(&file).unwrap();
            // The inputs carry ${FW_PORT}, which the harness substitutes;
            // supply it here so the port binds as an integer.
            let mut ctx = context();
            ctx.environment = vec![(js("FW_PORT"), js("2222"))];
            bind_devices_bytes(text.as_bytes(), &ctx).unwrap_or_else(|e| panic!("{}: {e:?}", file.display()));
            bound += 1;
        }
    }
    assert!(bound > 0, "expected fake-worker Marathondevices inputs");
}

// ---- Pipeline staging ----------------------------------------------------------

#[test]
fn f4_relative_key_stays_relative_and_verbatim() {
    // F4 (confirmed): the P2 File deserializer neither resolves against
    // the Marathonfile dir nor canonicalizes; resolution happens when a
    // consumer opens the key, against the process working directory.
    let devices = bind(
        "workers: [{transport: {type: ssh, addr: node, authentication: {type: publicKey, username: u, key: \"relative/dir/key.pem\"}}, devices: []}]",
    )
    .unwrap();
    let Transport::Ssh {
        authentication: Some(SshAuthentication::PublicKey { key, .. }),
        ..
    } = &devices.workers[0].transport
    else {
        panic!("expected ssh publicKey")
    };
    assert_eq!(key.to_string_lossy().into_owned(), "relative/dir/key.pem");
}

#[test]
fn provider_stage_and_error_distinctions() {
    // Provider stage, original class, no P1 wrapper.
    let Err(LoadError::Configuration(error)) = bind("workers: [{transport: {type: local}, devices: [], bogus: 1}]")
    else {
        panic!("expected a binding error");
    };
    assert_eq!(error.stage, ValidationStage::Provider);
    assert_eq!(
        error.class.to_owned(),
        "com.fasterxml.jackson.databind.exc.UnrecognizedPropertyException"
    );
    assert!(matches!(error.cause, BindingCause::Coercion(_)));

    // A YAML stream failure is distinguishable from a coercion failure,
    // which is what the providers' JsonMappingException-only catch needs.
    let Err(LoadError::Configuration(error)) = bind("workers: [") else {
        panic!("expected a binding error");
    };
    assert_eq!(error.stage, ValidationStage::Provider);
    assert!(matches!(error.cause, BindingCause::Stream(_)), "{error:?}");

    // A leading null document is its own outcome, not an empty list.
    assert!(matches!(bind("null"), Err(LoadError::NullDocument)));
    // Empty workers binds fine; "No workers found" is the providers' check.
    assert_eq!(bind("workers: []").unwrap().workers.len(), 0);
    // Substitution runs before binding and escapes unwrapped.
    let mut ctx = context();
    ctx.environment = vec![(js("ADDR"), js("node-9"))];
    let devices = bind_devices_bytes(
        "workers: [{transport: {type: ssh, addr: ${ADDR}}, devices: []}]".as_bytes(),
        &ctx,
    )
    .unwrap();
    let Transport::Ssh { addr, .. } = &devices.workers[0].transport else {
        panic!("expected ssh")
    };
    assert_eq!(addr.to_owned(), "node-9");
}

// ---- P2 oracle corpus ------------------------------------------------------------

fn s(value: &str) -> Json {
    value.to_owned().into()
}

fn canonical(devices: &MarathonDevices) -> Json {
    json!({
        "workers": devices.workers.iter().map(|worker| json!({
            "transport": match &worker.transport {
                Transport::Local => json!({"type": "local"}),
                Transport::Ssh { addr, port, check_reachability, authentication } => json!({
                    "type": "ssh",
                    "addr": s(addr),
                    "port": port,
                    "checkReachability": check_reachability,
                    "authentication": match authentication {
                        None => Json::Null,
                        Some(SshAuthentication::Password { username, password }) =>
                            json!({"type": "password", "username": s(username), "password": s(password)}),
                        Some(SshAuthentication::PublicKey { username, key }) =>
                            json!({"type": "publicKey", "username": s(username), "key": key.to_string_lossy().into_owned()}),
                    },
                }),
            },
            "devices": worker.devices.iter().map(|target| match target {
                AppleTarget::Simulator { udid } => json!({"type": "simulator", "udid": s(udid)}),
                AppleTarget::Physical { udid } => json!({"type": "physical", "udid": s(udid)}),
                AppleTarget::SimulatorProfile(profile) => json!({
                    "type": "simulatorProfile",
                    "deviceType": s(&profile.device_type_id),
                    "runtime": profile.runtime_id.as_ref().map_or(Json::Null, |text| s(text)),
                    "newNamePrefix": s(&profile.new_name_prefix),
                    "fqDeviceType": s(&profile.fully_qualified_device_type_id()),
                    "fqRuntime": profile.fully_qualified_runtime_id().as_ref().map_or(Json::Null, |text| s(text)),
                }),
                AppleTarget::Host => json!({"type": "host"}),
            }).collect::<Vec<_>>(),
        })).collect::<Vec<_>>(),
    })
}

#[test]
fn devices_corpus_matches_jvm() {
    // D9 (WP 2.2 S4): Kotlin keeps null collection elements (F10); the
    // port rejects them at bind time. These two rows are the intentional
    // divergence, with the rejection class asserted instead.
    const D9_NULL_ELEMENTS: [&str; 2] = ["workers-null-element", "worker-devices-null-element"];
    let table = fs::read_to_string(
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle/yaml-devices-corpus.jsonl"),
    )
    .unwrap();
    let mut checked = 0;
    for line in table.lines().skip(1) {
        let row: Json = serde_json::from_str(line).unwrap();
        let id = row["id"].as_str().unwrap();
        let input = row["input"].as_str().unwrap();
        let result = &row["result"];
        checked += 1;
        match bind_devices_bytes(input.as_bytes(), &context()) {
            Ok(devices) => {
                assert!(
                    result.get("ok").is_some_and(|ok| !ok.is_null()),
                    "{id}: JVM gave {result}"
                );
                assert_eq!(canonical(&devices), result["ok"], "{id}");
            }
            Err(LoadError::NullDocument) => {
                assert_eq!(result["ok"], Json::Null, "{id}: expected a null document on the JVM");
            }
            Err(LoadError::Configuration(error)) => {
                if D9_NULL_ELEMENTS.contains(&id) {
                    assert_eq!(
                        error.class.to_owned(),
                        "com.fasterxml.jackson.databind.exc.MismatchedInputException",
                        "{id} (D9 null-element rejection)"
                    );
                    continue;
                }
                let expected = &result["error"];
                assert!(
                    !expected.is_null(),
                    "{id}: JVM bound {}, Rust failed {error:?}",
                    result["ok"]
                );
                assert_eq!(
                    error.class.to_owned(),
                    expected["class"].as_str().unwrap(),
                    "{id} class"
                );
                assert_eq!(error.stage, ValidationStage::Provider, "{id} stage");
            }
            Err(other) => panic!("{id}: {other:?}"),
        }
    }
    assert_eq!(checked, 56);
}
